func TestDoctorHelpQualifiesLiveSandboxExamples(t *testing.T) {
	helpOut, helpErr, err := runCLIForAuthTest(t, "", "doctor", "--help")
	if err != nil {
		t.Fatalf("doctor --help returned error: %v", err)
	}

	text := helpOut + helpErr
	if !strings.Contains(text, "straddle-pp-cli setup check --json") {
		t.Fatalf("doctor help should start from setup check, got %q", text)
	}
	if !strings.Contains(text, "optional live sandbox reachability") ||
		!strings.Contains(text, "explicit sandbox base URL and credentials") {
		t.Fatalf("doctor help should qualify live sandbox reachability, got %q", text)
	}
	if strings.Contains(text, "\n  straddle-pp-cli doctor\n") || strings.Contains(text, "\n  straddle-pp-cli doctor --fail-on warn\n") {
		t.Fatalf("doctor help must not include standalone unqualified live examples, got %q", text)
	}
}

func TestDoctorJSONUnauthenticatedRoutesThroughSetupCheck(t *testing.T) {
	t.Setenv("STRADDLE_TOKEN", "")
	t.Setenv("STRADDLE_BASE_URL", "")
	configPath := filepath.Join(t.TempDir(), "config.toml")
	if err := os.WriteFile(configPath, []byte("base_url = \"\"\n"), 0o600); err != nil {
		t.Fatalf("write config: %v", err)
	}

	stdout, stderr, err := runCLIForAuthTest(t, "", "doctor", "--json", "--config", configPath)
	if err != nil {
		t.Fatalf("doctor --json returned error: %v\nstderr: %s", err, stderr)
	}

	var report map[string]any
	if err := json.Unmarshal([]byte(stdout), &report); err != nil {
		t.Fatalf("parse doctor JSON: %v\nstdout: %s", err, stdout)
	}
	hint, ok := report["auth_hint"].(string)
	if !ok || hint == "" {
		t.Fatalf("doctor JSON should include auth_hint, got %#v", report["auth_hint"])
	}
	assertCLIAuthReadinessGuidance(t, hint)
}
